sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var segment = current.getValue('segment').toLowerCase();

    // Safely strip all currency prefixes and commas before parsing
    var rawPanExp = current.getValue('total_net_exposure') || '0';
    var panNetExposure = parseFloat(rawPanExp.toString().replace(/[^0-9.-]+/g, ""));

    var isPanOverride = (panNetExposure > 15000000); // Trigger PAN roles if > 1.5 Cr
    var isDeviation = (current.getValue('is_deviation') == '1' || current.getValue('is_deviation') == 'true');

    // 1. Initialize Deduplication Arrays for every field
    var fields = {
        nt_cement_rhm: [],
        nt_cement_zhm: [],
        nt_cement_zch: [],
        nt_cement_nsh: [],
        nt_rmc_tsm: [],
        nt_rmc_rh_ch: [],
        nt_rmc_zh: [],
        nt_rmc_zch: [],
        nt_rmc_head_rmc: [],
        nt_rmc_national_head_key: [],
        nt_rmc_ch_rmc: [],
        nt_bpd_tsh: [],
        nt_bpd_zh_bpd: [],
        nt_bpd_hs_bpd: [],
        nt_bpd_zch: [],
        nt_bpd_h_bpd: [],
        pan_ho: [],
        pan_cch: [],
        pan_cmo_bh: [],
        pan_cfo: [],
        pan_md: []
    };

    // NEW: Global tracker to prevent a user from being asked twice across ANY tier
    var globalApprovers = [];

    function addUnique(arrayKey, userId) {
        if (userId) {
            var uid = userId.toString();
            // If they aren't in this specific field YET, AND they haven't been added to any previous field
            if (fields[arrayKey].indexOf(uid) === -1 && globalApprovers.indexOf(uid) === -1) {
                fields[arrayKey].push(uid);
                globalApprovers.push(uid); // Mark them as officially in the approval chain
            }
        }
    }

    // Helper function to keep mapping clean
    function mapRole(role, approver, isPanIndia) {
        switch (role) {
            case 'NT CEMENT RHM':
                addUnique('nt_cement_rhm', approver);
                break;
            case 'NT CEMENT ZHM':
                addUnique('nt_cement_zhm', approver);
                break;
            case 'NT CEMENT ZCH':
                addUnique('nt_cement_zch', approver);
                break;
            case 'NT CEMENT NSH':
                addUnique('nt_cement_nsh', approver);
                break;

            case 'NT RMC TSM':
                addUnique('nt_rmc_tsm', approver);
                break;
            case 'NT RMC RH CH':
                addUnique('nt_rmc_rh_ch', approver);
                break;
            case 'NT RMC ZCH':
                addUnique('nt_rmc_zch', approver);
                break;
            case 'NT RMC ZH':
                addUnique('nt_rmc_zh', approver);
                break;
            case 'NT RMC HEAD RMC':
                addUnique('nt_rmc_head_rmc', approver);
                break;
            case 'NT RMC NATIONAL HEAD KEY':
                addUnique('nt_rmc_national_head_key', approver);
                break;
            case 'NT RMC CH RMC':
                addUnique('nt_rmc_ch_rmc', approver);
                break;

            case 'NT BPD TSH':
                addUnique('nt_bpd_tsh', approver);
                break;
            case 'NT BPD ZH BPD':
                addUnique('nt_bpd_zh_bpd', approver);
                break;
            case 'NT BPD HS BPD':
                addUnique('nt_bpd_hs_bpd', approver);
                break;
            case 'NT BPD ZCH':
                addUnique('nt_bpd_zch', approver);
                break;
            case 'NT BPD HBPD':
                addUnique('nt_bpd_h_bpd', approver);
                break;

                // PAN Roles
            case 'HO':
                addUnique('pan_ho', approver);
                break;
            case 'CCH':
                addUnique('pan_cch', approver);
                break;
            case 'CMO BH':
                addUnique('pan_cmo_bh', approver);
                break;
            case 'CFO':
                addUnique('pan_cfo', approver);
                break;
            case 'MD':
                addUnique('pan_md', approver);
                break;
        }
    }

    // 2. Loop through all associated Child Site Requests
    var siteGr = new GlideRecord('x_birl3_clm_nt_site_request');
    siteGr.addQuery('pan_request', current.getUniqueValue());
    siteGr.query();

    while (siteGr.next()) {

        var rawSiteExp = current.getValue('segment_net_exposure') || '0';
        var siteExposure = parseFloat(rawSiteExp.toString().replace(/[^0-9.-]+/g, ""));

        // NEW: Fetch Requested Number of Days (NOD) from Site record[cite: 3]
        var siteNod = parseInt(siteGr.getValue('nod')) || 0;

        var zone = siteGr.customer_site_code.zone || '';
        var region = siteGr.customer_site_code.region || '';
        var depot = siteGr.customer_site_code.depot || '';

        // Reset the +1 escalation flag for each site request
        var requiresEscalation = isDeviation;

        // 3. Query Master Matrix with Hierarchical Rollup Logic
        var mxGr = new GlideRecord('x_birl3_clm_approval_matrix');
        mxGr.addQuery('customer_type', 'non_trade');

        var encodedQuery = 'segment=' + segment + '^ORsegmentISEMPTY';
        encodedQuery += '^zone=' + zone + '^ORzoneISEMPTY';
        encodedQuery += '^region=' + region + '^ORregionISEMPTY';
        encodedQuery += '^depot=' + depot + '^ORdepotISEMPTY';

        mxGr.addEncodedQuery(encodedQuery);
        mxGr.orderBy('sequence_order'); // Crucial: Ensures lowest tier to highest tier
        mxGr.query();

        while (mxGr.next()) {
            var role = mxGr.getValue('role_name');
            var approver = mxGr.getValue('approver_user');
            var minAmt = parseFloat(mxGr.getValue('min_amount')) || 0;

            // NEW: Fetch Allowed Number of Days from Matrix
            var matrixNod = parseInt(mxGr.getValue('number_of_days')) || 0;

            var isPanIndia = (mxGr.getValue('pan_india') == '1' || mxGr.getValue('pan_india') == 'true');

            if (!approver) continue;

            // NEW: Calculate if Threshold is Breached (Amount OR NOD)
            var amountBreached = (siteExposure > minAmt);
            var nodBreached = (matrixNod > 0 && siteNod > matrixNod);
            var thresholdMet = (amountBreached || nodBreached);

            // 4. Matrix Threshold Check FOR SEGMENTS
            if (thresholdMet && !isPanIndia) {
                // Naturally triggered by exposure limit or NOD limit
                mapRole(role, approver, isPanIndia);
            }
            // +1 DEVIATION ESCALATION CHECK
            else if (requiresEscalation && !isPanIndia) {
                // This is the first role that failed the threshold check. Push them into the array.
                mapRole(role, approver, isPanIndia);
                // Immediately disable the flag so it only escalates +1 level.
                requiresEscalation = false;
            }

            // 5. PAN-Level Override Check
            if (isPanOverride && isPanIndia && (panNetExposure > minAmt)) {
                mapRole(role, approver, isPanIndia);
            }
            // Spillover +1 Escalation (If deviation pushes a top-tier segment directly into PAN level)
            else if (requiresEscalation && isPanIndia) {
                mapRole(role, approver, isPanIndia);
                requiresEscalation = false;
            }
        }
    }

    // 6. Write Data back to the specific PAN Request Fields
    for (var key in fields) {
        if (current.isValidField(key)) {
            current.setValue(key, fields[key].join(','));
        }
    }

})(current, previous);
